"use strict";const EventEmitter=require("events");class MessengerContext{constructor(bot,event){this.bot=bot;this.event=event}get threadID(){return this.event.threadID}get senderID(){return this.event.senderID}get messageID(){return this.event.messageID}get text(){return(this.event.body||"").trim()}get body(){return this.event.body}get message(){return this.event}reply(payload,callback){const tid=this.event.threadID;if(tid==null)throw new Error("MessengerContext.reply: threadID is missing");return this.bot.api.sendMessage(payload,tid,callback)}async replyAsync(payload){const r=this.reply(payload);if(r&&typeof r.then==="function")return r;return Promise.resolve(r)}}function escapeRegex(s){return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}function emitIf(bot,channel,payload){if(bot.listenerCount(channel)>0)bot.emit(channel,payload)}function emitGatewayEvents(bot,event){emitIf(bot,"update",event);emitIf(bot,"raw",event);const t=event.type;if(!t)return;if(t==="message"||t==="message_reply"){emitIf(bot,"message",event);emitIf(bot,"messageCreate",event)}if(t==="message_reply"){emitIf(bot,"message_reply",event)}else if(t!=="message"){emitIf(bot,t,event)}switch(t){case"message_reaction":emitIf(bot,"messageReactionAdd",event);break;case"message_unsend":emitIf(bot,"messageDelete",event);break;case"typ":emitIf(bot,event.isTyping?"typingStart":"typingStop",event);break;case"event":emitIf(bot,"threadUpdate",event);break;case"ready":emitIf(bot,"ready",event);emitIf(bot,"shardReady",event);break}}class MessengerBot extends EventEmitter{constructor(api,options={}){super();this.api=api;this.options=Object.assign({commandPrefix:"/",enableComposer:true,autoListen:true,stopOnSignals:false,maxEventListeners:64},options);if(this.options.maxEventListeners>0){this.setMaxListeners(this.options.maxEventListeners)}this._middleware=[];this._commands=new Map;this._hears=[];this._catchHandler=null;this._mqttHandle=null;this._signalHandlers=null}use(fn){this._middleware.push(fn);return this}command(name,fn){this._commands.set(String(name).toLowerCase(),fn);return this}hears(trigger,fn){this._hears.push({trigger:trigger,fn:fn});return this}catch(fn){this._catchHandler=fn;return this}async _runComposer(event){if(!this.options.enableComposer)return;if(event.type!=="message"&&event.type!=="message_reply")return;const ctx=new MessengerContext(this,event);const prefix=this.options.commandPrefix||"/";const body=event.body||"";const trimmed=body.trim();const pipeline=[...this._middleware];if(trimmed.startsWith(prefix)){const withoutPrefix=trimmed.slice(prefix.length);const cmdName=withoutPrefix.split(/\s+/)[0].toLowerCase();if(this._commands.has(cmdName)){pipeline.push(this._commands.get(cmdName))}}else{for(const{trigger:trigger,fn:fn}of this._hears){if(typeof trigger==="string"){if(trimmed.toLowerCase().includes(trigger.toLowerCase())){pipeline.push(fn)}}else if(trigger instanceof RegExp){if(trigger.test(trimmed)){pipeline.push(fn)}}}}let idx=0;const next=async()=>{if(idx>=pipeline.length)return;const fn=pipeline[idx++];try{await fn(ctx,next)}catch(err){if(this._catchHandler){this._catchHandler(err,ctx)}else{this.emit("error",err)}}};await next()}startListening(){if(this._mqttHandle)return this._mqttHandle;if(this.api&&this.api.ctx&&this.api.ctx._listeningActive){this._mqttHandle=this.api.ctx._emitter||{stopListening:()=>{}};return this._mqttHandle}this._mqttHandle=this.api.listenMqtt((err,event)=>{if(err){this.emit("error",err);return}emitGatewayEvents(this,event);this._runComposer(event).catch(e=>this.emit("error",e))});return this._mqttHandle}stopListening(){if(this._mqttHandle&&typeof this._mqttHandle.stopListening==="function"){this._mqttHandle.stopListening()}else if(this.api&&typeof this.api.stopListening==="function"){this.api.stopListening()}this._mqttHandle=null}async stop(){if(this._signalHandlers){for(const[sig,handler]of Object.entries(this._signalHandlers)){process.removeListener(sig,handler)}this._signalHandlers=null}this.stopListening();this.removeAllListeners()}async launch(launchOptions={}){const opts=Object.assign({},this.options,launchOptions);if(opts.stopOnSignals){const handler=async()=>{await this.stop();process.exit(0)};this._signalHandlers={SIGINT:handler,SIGTERM:handler};process.once("SIGINT",handler);process.once("SIGTERM",handler)}if(opts.autoListen!==false){this.startListening()}}}async function createMessengerBot(credentials,options={}){const{login:login}=require("../engine/client");const api=await login(credentials,options);const bot=new MessengerBot(api,options);if(options.autoListen!==false){bot.startListening()}return bot}module.exports={MessengerBot:MessengerBot,MessengerContext:MessengerContext,createMessengerBot:createMessengerBot};
